{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "PBR102, a close analogue sharing the diethylamide-acetamide and para-substituted phenyl motif, showed high initial brain uptake in non-human primate PET-CT, supporting BBB permeability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "The close analogue [18F]-(R)-TRACK, with the same diethylamide-acetamide core and para-substituted phenyl group, passed the BBB with high brain uptake in non-human primates.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Alpidem, a structurally related imidazopyridine amide, easily crossed the BBB in rats with brain/plasma ratios of about 2.0-2.5 after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "PI1, a diethylamide-containing brain-penetrant NPSR antagonist, reached good CSF concentrations after intraperitoneal dosing in rats, demonstrating meaningful CNS access for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "The O-[11C]methylphenyl-containing radiotracer [11C]5i showed moderate whole-brain uptake (SUV 1.16) in mice, directly supporting the brain permeability of the query's radiolabeled methoxy motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "A diethylaminoethyl amide analogue showed moderate mouse brain uptake (2.46 %ID/g at 10 min), confirming that this amide/aryl class can cross the BBB.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass: all high-transfer experimental analogues consistently demonstrate meaningful BBB/CNS access, including close structural relatives with the same diethylamide/heteroaryl core and para-substituted phenyl radiotracer motif. No contradictory evidence was retrieved.",
  "evidence_gaps": [
    "No direct human or quantitative CSF/plasma measurement for the exact query molecule.",
    "Efflux-transporter status was not explicitly measured for the query, but consistent in vivo brain uptake across close analogues mitigates this gap."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

